/// The legacy embedded engine's parameter list builder (Task A4a thin shim: delegates to
/// `storage::api::params!`; call-site shape at the 423 usages is unchanged).
macro_rules! fparams {
    () => {
        &[] as &[ParamValue]
    };
    ($($val:expr),+ $(,)?) => {
        &crate::storage::api::params![$($val),+] as &[ParamValue]
    };
}
