    /// franken 6-role normalization contract (task 2.1): `"assistant"` must
    /// survive the store->read round-trip as its own role string, not
    /// collapse into the legacy `"agent"` spelling. Covers both production
    /// read paths (`fetch_messages` and the lexical-rebuild projection) plus
    /// a direct check of the raw DB `role` TEXT column.
    #[test]
    fn assistant_roundtrips_not_collapsed_to_agent() {
        let dir = TempDir::new().unwrap();
        let db_path = dir.path().join("assistant-roundtrip.db");
        let storage = SqliteStorage::open(&db_path).unwrap();

        let agent = Agent {
            id: None,
            slug: "codex".into(),
            name: "Codex".into(),
            version: Some("0.2.3".into()),
            kind: AgentKind::Cli,
        };
        let agent_id = storage.ensure_agent(&agent).unwrap();

        let conversation = Conversation {
            id: None,
            agent_slug: "codex".into(),
            workspace: Some(PathBuf::from("/tmp/workspace")),
            external_id: Some("assistant-roundtrip-test".into()),
            title: Some("6-role roundtrip".into()),
            source_path: PathBuf::from("/tmp/assistant-roundtrip.jsonl"),
            started_at: Some(1_700_000_000_000),
            ended_at: Some(1_700_000_000_300),
            approx_tokens: None,
            metadata_json: serde_json::Value::Null,
            messages: vec![
                Message {
                    id: None,
                    idx: 0,
                    role: role_from_str("user"),
                    author: None,
                    created_at: Some(1_700_000_000_010),
                    content: "hello".into(),
                    extra_json: serde_json::Value::Null,
                    snippets: Vec::new(),
                },
                Message {
                    id: None,
                    idx: 1,
                    role: role_from_str("assistant"),
                    author: None,
                    created_at: Some(1_700_000_000_020),
                    content: "hi there".into(),
                    extra_json: serde_json::Value::Null,
                    snippets: Vec::new(),
                },
                Message {
                    id: None,
                    idx: 2,
                    role: role_from_str("tool_result"),
                    author: None,
                    created_at: Some(1_700_000_000_030),
                    content: "result payload".into(),
                    extra_json: serde_json::Value::Null,
                    snippets: Vec::new(),
                },
            ],
            source_id: LOCAL_SOURCE_ID.into(),
            origin_host: None,
        };

        let inserted = storage
            .insert_conversation_tree(agent_id, None, &conversation)
            .unwrap();
        let conversation_id = inserted.conversation_id;

        // Direct read path.
        let stored = storage.fetch_messages(conversation_id).unwrap();
        assert_eq!(stored.len(), 3);
        assert_eq!(
            role_as_str(&stored[1].role),
            "assistant",
            "assistant role must round-trip as \"assistant\", not collapse to \"agent\""
        );
        assert_ne!(
            stored[1].role,
            MessageRole::Agent,
            "assistant-tagged message must not be read back as the legacy Agent variant"
        );
        assert_eq!(
            role_as_str(&stored[2].role),
            "tool_result",
            "tool_result must survive the store->read round-trip unchanged"
        );

        // The other production read path (lexical-rebuild projection) must
        // agree — it shares the same `role_from_str` call, but assert it
        // directly since it used to be an independently hand-rolled parser.
        let lexical = storage
            .fetch_messages_for_conversation(conversation_id)
            .unwrap();
        assert_eq!(lexical.len(), 3);
        assert_eq!(role_as_str(&lexical[1].role), "assistant");
        assert_eq!(role_as_str(&lexical[2].role), "tool_result");

        // The raw DB TEXT column itself must never have collapsed either —
        // this is the ground truth downstream consumers (e.g. search) read.
        let raw_role: String = storage
            .conn
            .query_row_map(
                "SELECT role FROM messages WHERE conversation_id = ?1 AND idx = ?2",
                fparams![conversation_id, 1_i64],
                |row| row.get_typed(0),
            )
            .unwrap();
        assert_eq!(raw_role, "assistant");
    }

    /// franken 6-role normalization contract (task 2.1): a non-empty `extra`
    /// payload serializes into `extra_bin` (msgpack), leaving `extra_json`
    /// NULL (see `franken_message_insert_payload`). SQL `json_extract` on
    /// `extra_json` is therefore always NULL for this shape — only
    /// `fetch_messages` (via `franken_read_message_extra_compat`) decodes
    /// `extra_bin` back, so it is the only path that can prove a
    /// `tool_call_id` pairing key survives the round-trip.
    #[test]
    fn tool_result_pairing_survives_extra_bin_roundtrip() {
        let dir = TempDir::new().unwrap();
        let db_path = dir.path().join("tool-result-pairing.db");
        let storage = SqliteStorage::open(&db_path).unwrap();

        let agent = Agent {
            id: None,
            slug: "codex".into(),
            name: "Codex".into(),
            version: Some("0.2.3".into()),
            kind: AgentKind::Cli,
        };
        let agent_id = storage.ensure_agent(&agent).unwrap();

        let conversation = Conversation {
            id: None,
            agent_slug: "codex".into(),
            workspace: Some(PathBuf::from("/tmp/workspace")),
            external_id: Some("tool-result-pairing-test".into()),
            title: Some("tool_result pairing".into()),
            source_path: PathBuf::from("/tmp/tool-result-pairing.jsonl"),
            started_at: Some(1_700_000_000_000),
            ended_at: Some(1_700_000_000_200),
            approx_tokens: None,
            metadata_json: serde_json::Value::Null,
            messages: vec![Message {
                id: None,
                idx: 0,
                role: role_from_str("tool_result"),
                author: None,
                created_at: Some(1_700_000_000_010),
                content: "tool ran".into(),
                extra_json: serde_json::json!({ "tool_call_id": "tu_1" }),
                snippets: Vec::new(),
            }],
            source_id: LOCAL_SOURCE_ID.into(),
            origin_host: None,
        };

        let inserted = storage
            .insert_conversation_tree(agent_id, None, &conversation)
            .unwrap();
        let conversation_id = inserted.conversation_id;

        // Confirm this row actually took the extra_bin (msgpack) path, not
        // extra_json, so the assertion below genuinely exercises the
        // msgpack decode rather than the plain-JSON shortcut.
        let (extra_json_col, extra_bin_col): (Option<String>, Option<Vec<u8>>) = storage
            .conn
            .query_row_map(
                "SELECT extra_json, extra_bin FROM messages WHERE conversation_id = ?1 AND idx = ?2",
                fparams![conversation_id, 0_i64],
                |row| Ok((row.get_typed(0)?, row.get_typed(1)?)),
            )
            .unwrap();
        assert!(
            extra_json_col.is_none(),
            "non-empty extra must serialize into extra_bin, leaving extra_json NULL"
        );
        assert!(
            extra_bin_col.is_some(),
            "tool_call_id payload must be present in extra_bin (msgpack)"
        );

        let stored = storage.fetch_messages(conversation_id).unwrap();
        assert_eq!(stored.len(), 1);
        assert_eq!(role_as_str(&stored[0].role), "tool_result");
        let tool_call_id = stored[0]
            .extra_json
            .get("tool_call_id")
            .and_then(|v| v.as_str());
        assert_eq!(
            tool_call_id,
            Some("tu_1"),
            "tool_call_id must survive the extra_bin msgpack round-trip via fetch_messages"
        );
        println!("TOOLRESULT_PAIRED_ROUNDTRIP_OK");
    }

    #[test]
    fn fetch_messages_for_conversations_batch_groups_and_orders_messages() {
        let dir = TempDir::new().unwrap();
        let db_path = dir.path().join("test.db");
        let storage = SqliteStorage::open(&db_path).unwrap();

        let agent = Agent {
            id: None,
            slug: "codex".into(),
            name: "Codex".into(),
            version: Some("0.2.3".into()),
            kind: AgentKind::Cli,
        };
        let agent_id = storage.ensure_agent(&agent).unwrap();

        let first = Conversation {
            id: None,
            agent_slug: "codex".into(),
            workspace: Some(PathBuf::from("/tmp/workspace")),
            external_id: Some("lexical-batch-1".into()),
            title: Some("Lexical batch 1".into()),
            source_path: PathBuf::from("/tmp/lexical-batch-1.jsonl"),
            started_at: Some(1_700_000_000_000),
            ended_at: Some(1_700_000_000_100),
            approx_tokens: Some(42),
            metadata_json: serde_json::Value::Null,
            messages: vec![
                Message {
                    id: None,
                    idx: 0,
                    role: MessageRole::User,
                    author: Some("user".into()),
                    created_at: Some(1_700_000_000_010),
                    content: "first-a".into(),
                    extra_json: serde_json::json!({"opaque": true}),
                    snippets: Vec::new(),
                },
                Message {
                    id: None,
                    idx: 1,
                    role: MessageRole::Agent,
                    author: Some("assistant".into()),
                    created_at: Some(1_700_000_000_020),
                    content: "first-b".into(),
                    extra_json: serde_json::json!({"opaque": true}),
                    snippets: Vec::new(),
                },
            ],
            source_id: LOCAL_SOURCE_ID.into(),
            origin_host: None,
        };

        let second = Conversation {
            id: None,
            agent_slug: "codex".into(),
            workspace: Some(PathBuf::from("/tmp/workspace")),
            external_id: Some("lexical-batch-2".into()),
            title: Some("Lexical batch 2".into()),
            source_path: PathBuf::from("/tmp/lexical-batch-2.jsonl"),
            started_at: Some(1_700_000_000_200),
            ended_at: Some(1_700_000_000_300),
            approx_tokens: Some(84),
            metadata_json: serde_json::Value::Null,
            messages: vec![Message {
                id: None,
                idx: 0,
                role: MessageRole::Tool,
                author: Some("tool".into()),
                created_at: Some(1_700_000_000_210),
                content: "second-a".into(),
                extra_json: serde_json::json!({"opaque": true}),
                snippets: Vec::new(),
            }],
            source_id: LOCAL_SOURCE_ID.into(),
            origin_host: None,
        };
        let third = Conversation {
            external_id: Some("lexical-batch-3".into()),
            title: Some("Lexical batch 3".into()),
            source_path: PathBuf::from("/tmp/lexical-batch-3.jsonl"),
            messages: vec![Message {
                id: None,
                idx: 0,
                role: MessageRole::System,
                author: Some("system".into()),
                created_at: Some(1_700_000_000_410),
                content: "third-a".into(),
                extra_json: serde_json::json!({"opaque": true}),
                snippets: Vec::new(),
            }],
            ..second.clone()
        };

        let first_id = storage
            .insert_conversation_tree(agent_id, None, &first)
            .unwrap()
            .conversation_id;
        let second_id = storage
            .insert_conversation_tree(agent_id, None, &second)
            .unwrap()
            .conversation_id;
        let third_id = storage
            .insert_conversation_tree(agent_id, None, &third)
            .unwrap()
            .conversation_id;

        let lexical = storage
            .fetch_messages_for_conversations_batch(&[third_id, first_id])
            .unwrap();

        let first_messages = lexical.get(&first_id).expect("first conversation");
        assert_eq!(first_messages.len(), 2);
        assert_eq!(first_messages[0].content, "first-a");
        assert_eq!(first_messages[1].content, "first-b");
        assert!(
            first_messages
                .iter()
                .all(|message| message.extra_json.is_null())
        );

        assert!(
            !lexical.contains_key(&second_id),
            "batch fetch must exclude conversations not requested by the caller"
        );

        let third_messages = lexical.get(&third_id).expect("third conversation");
        assert_eq!(third_messages.len(), 1);
        assert_eq!(third_messages[0].content, "third-a");
        assert!(third_messages[0].extra_json.is_null());
    }

    // T5 (plan v5.1): `fetch_messages_for_lexical_rebuild_batch_enforces_
    // content_byte_guardrail` retired -- it tested the `max_messages`/
    // `max_content_bytes` guardrail params, which are deleted along with
    // `fetch_messages_for_conversations_batch`'s rename (every call site
    // always passed `None, None`; dead parameters, and their whole premise
    // -- capping how much lexical content a batch fetch may return --
    // contradicts T5's "no cap" mandate).

    #[test]
    fn fetch_messages_handles_manual_rows_inserted_via_raw_connection() {
        let dir = TempDir::new().unwrap();
        let db_path = dir.path().join("manual-rows.db");
        let storage = FrankenStorage::open(&db_path).unwrap();
        let conn = storage.raw();

        conn.execute(
            "INSERT INTO agents (id, slug, name, kind, created_at, updated_at)
             VALUES (1, 'claude_code', 'Claude Code', 'local', 0, 0)",
        &[])
        .unwrap();
        conn.execute(
            "INSERT INTO conversations
             (id, agent_id, external_id, title, source_path, source_id, started_at)
             VALUES (1, 1, 'manual-ext', 'Manual Session', '/tmp/manual.jsonl', 'local', 200)",
        &[])
        .unwrap();
        conn.execute(
            "INSERT INTO messages
             (id, conversation_id, idx, role, author, created_at, content, extra_json, extra_bin)
             VALUES (1, 1, 0, 'user', 'tester', 1700000000000, 'manual body', '{\"k\":1}', NULL)",
        &[])
        .unwrap();

        let lexical = storage.fetch_messages_for_conversation(1).unwrap();
        assert_eq!(lexical.len(), 1);
        assert_eq!(lexical[0].content, "manual body");

        let full = storage.fetch_messages(1).unwrap();
        assert_eq!(full.len(), 1);
        assert_eq!(full[0].content, "manual body");
        assert_eq!(full[0].author.as_deref(), Some("tester"));
        assert_eq!(full[0].extra_json, serde_json::json!({ "k": 1 }));
    }

    #[test]
    fn lexical_rebuild_batch_messages_query_avoids_sorter_temp_btrees() {
        use crate::model::types::{Agent, AgentKind, Conversation, Message, MessageRole};
        use std::path::PathBuf;

        let dir = TempDir::new().unwrap();
        let db_path = dir.path().join("agent_search.db");
        let storage = SqliteStorage::open(&db_path).unwrap();

        let agent = Agent {
            id: None,
            slug: "claude_code".into(),
            name: "Claude Code".into(),
            version: None,
            kind: AgentKind::Cli,
        };
        let agent_id = storage.ensure_agent(&agent).unwrap();

        for (external_id, base_ts) in [
            ("conv-1", 1_700_000_000_000_i64),
            ("conv-2", 1_700_000_001_000_i64),
        ] {
            let conversation = Conversation {
                id: None,
                agent_slug: "claude_code".into(),
                workspace: Some(PathBuf::from("/tmp/workspace")),
                external_id: Some(external_id.to_string()),
                title: Some("Lexical rebuild".into()),
                source_path: PathBuf::from(format!("/tmp/{external_id}.jsonl")),
                started_at: Some(base_ts),
                ended_at: Some(base_ts + 100),
                approx_tokens: None,
                metadata_json: serde_json::Value::Null,
                messages: vec![
                    Message {
                        id: None,
                        idx: 0,
                        role: MessageRole::User,
                        author: Some("user".into()),
                        created_at: Some(base_ts + 10),
                        content: format!("{external_id}-first"),
                        extra_json: serde_json::Value::Null,
                        snippets: Vec::new(),
                    },
                    Message {
                        id: None,
                        idx: 1,
                        role: MessageRole::Agent,
                        author: Some("assistant".into()),
                        created_at: Some(base_ts + 20),
                        content: format!("{external_id}-second"),
                        extra_json: serde_json::Value::Null,
                        snippets: Vec::new(),
                    },
                ],
                source_id: LOCAL_SOURCE_ID.into(),
                origin_host: None,
            };
            storage
                .insert_conversation_tree(agent_id, None, &conversation)
                .unwrap();
        }

        let conversation_ids: Vec<i64> = storage
            .conn
            .query_all_map(
                "SELECT id FROM conversations ORDER BY id",
                fparams![],
                |row| row.get_typed(0),
            )
            .unwrap();
        assert_eq!(conversation_ids.len(), 2);

        let plan_details: Vec<String> = storage
            .conn
            .query_all_map(
                "EXPLAIN QUERY PLAN \
                 SELECT conversation_id, id, idx, role, author, created_at, content \
                 FROM messages \
                 WHERE conversation_id IN (?1, ?2) \
                 ORDER BY conversation_id ASC, idx ASC",
                fparams![conversation_ids[0], conversation_ids[1]],
                |row| row.get_typed(3),
            )
            .unwrap();

        assert!(
            plan_details
                .iter()
                .any(|detail| detail.contains("sqlite_autoindex_messages_1")),
            "expected batched lexical rebuild fetch to use the conversation_id/idx composite index, got {plan_details:?}"
        );
        assert!(
            !plan_details
                .iter()
                .any(|detail| detail.contains("TEMP B-TREE")),
            "expected batched lexical rebuild fetch to avoid sorter temp b-trees, got {plan_details:?}"
        );
    }

